const all = await items.list();
const js = await jira.listItems();
return {
 jira: js.map(j => j.gone ? j : {id:j.id, type:j.issueType, s:j.summary, st:j.status.name, pts:j.points, a:j.assignee?.name, c:j.comments.length}),
 others: all.filter(i=>!i.id.startsWith("jira:")).map(i=> i.gone? i : {id:i.id,title:i.title,len:i.text.length, text:i.text.slice(0,3000)})
};

